    69→ */
    70→public class ReportBuilder
    71→{
    72→	private final TemplateConfig			config;
    73→	private final Set<JRDesignField>		fieldSet	= new HashSet<>();
    74→	
    75→	
    76→	public ReportBuilder(final TemplateConfig tempConfig)
    77→	{
    78→		this.config = tempConfig;
    79→	}
    80→	
    81→	
    82→	private JRDesignBand initDetailBand()
    83→	{
