    85→		detailBand.setHeight(TemplateConfig.DEFAULT_DETAIL_BAND_HEIGHT);
    86→		detailBand.setSplitType(SplitTypeEnum.STRETCH);
    87→		
    88→		return detailBand;
    89→	}
