    92→	private JRDesignBand initHeaderBand()
    93→	{
    94→		// Header
    95→		final JRDesignBand headerBand = new JRDesignBand();
    96→		headerBand.setHeight(TemplateConfig.DEFAULT_HEADER_BAND_HEIGHT);
    97→		
    98→		return headerBand;
    99→	}
   100→	
   101→	
   102→	private JasperDesign createDefaultDesign()
   103→	{
   104→		final JasperDesign jasperDesign = new JasperDesign();
   105→		jasperDesign.setName("DefaultDesign");
   106→		final PageProperties properties = this.config.getPageProperties();
   107→		
   108→		jasperDesign.setPageWidth(this.calcPageWidth(properties));
   109→		jasperDesign.setColumnWidth(this.calcColumnsWidth());
   110→		
   111→		jasperDesign.setPageHeight(properties.getPageHeight());
   112→		jasperDesign.setColumnSpacing(properties.getColumnSpacing());
   113→		jasperDesign.setLeftMargin(properties.getLeftMargin());
   114→		jasperDesign.setRightMargin(properties.getRightMargin());
   115→		jasperDesign.setTopMargin(properties.getTopMargin());
   116→		jasperDesign.setBottomMargin(properties.getBottomMargin());
   117→		
   118→		return jasperDesign;
   119→	}
   120→	
   121→	
   122→	private int calcColumnsWidth()
   123→	{
   124→		int width = 0;
   125→		
   126→		for(final TemplateColumn col : this.config.getColumns())
   127→		{
   128→			width += col.getWidth();
   129→		}
   130→		
   131→		return width;
   132→	}
