   134→	/***
   135→	 * Calculated the page width including the margins.
   136→	 * 
   137→	 * @param properties
   138→	 * 
   139→	 * @return
   140→	 */
   141→	private int calcPageWidth(final PageProperties properties)
   142→	{
   143→		int width = 0;
   144→		
   145→		for(final TemplateColumn col : this.config.getColumns())
   146→		{
   147→			width += col.getWidth();
   148→		}
   149→		
   150→		width += properties.getLeftMargin() + properties.getRightMargin();
   151→		
   152→		return width;
   153→	}
