   214→	private void createTemplateFields(final JasperDesign jasperDesign) throws ExportException
   215→	{
   216→		JRDesignField field;
   217→		
   218→		for(final TemplateColumn col : this.config.getColumns())
   219→		{
   220→			field = new JRDesignField();
   221→			field.setName(col.getContentColumn().getFieldName());
   222→			this.chooseValueClass(col,field);
   223→			
   224→			try
   225→			{
   226→				jasperDesign.addField(field);
   227→				this.fieldSet.add(field);
   228→			}
   229→			catch(final JRException e)
   230→			{
   231→				throw new ExportException("error during add the field "
   232→						+ col.getContentColumn().getFieldName(),e);
   233→			}
   234→		}
   235→		
   236→	}
